{"command":"cat << 'EOF' > gen_cmatrix.py
import os

c_code = """
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <getopt.h>
#include <ncurses.h>
#include <time.h>

void print_help() {
    printf(" Usage: cmatrix -[abBcfhlsmVxk] [-u delay] [-C color] [-t tty] [-M message]\\n");
    printf(" -a: Asynchronous scroll\\n");
    printf(" -b: Bold characters on\\n");
    printf(" -B: All bold characters (overrides -b)\\n");
    printf(" -c: Use Japanese characters as seen in the original matrix. Requires appropriate fonts\\n");
    printf(" -f: Force the linux $TERM type to be on\\n");
    printf(" -l: Linux mode (uses matrix console font)\\n");
    printf(" -L: Lock mode (can be closed from another terminal)\\n");
    printf(" -o: Use old-style scrolling\\n");
    printf(" -h: Print usage and exit\\n");
    printf(" -n: No bold characters (overrides -b and -B, default)\\n");
    printf(" -s: \\"Screensaver\\" mode, exits on first keystroke\\n");
    printf(" -x: X window mode, use if your xterm is using mtx.pcf\\n");
    printf(" -V: Print version information and exit\\n");
    printf(" -M [message]: Prints your message in the center of the screen. Overrides -L's default message.\\n");
    printf(" -u delay (0 - 10, default 4): Screen update delay\\n");
    printf(" -C [color]: Use this color for matrix (default green)\\n");
    printf(" -r: rainbow mode\\n");
    printf(" -m: lambda mode\\n");
    printf(" -k: Characters change while scrolling. (Works without -o opt.)\\n");
    printf(" -t [tty]: Set tty to use\\n");
}

typedef struct {
    int y;
    int len;
    int speed;
    int tick;
} Column;

int main(int argc, char **argv) {
    int opt;
    int async_scroll = 0;
    int all_bold = 0;
    int random_bold = 0;
    int force_term = 0;
    int linux_mode = 0;
    int lock_mode = 0;
    int old_scroll = 0;
    int screensaver = 0;
    int x_mode = 0;
    int rainbow_mode = 0;
    int lambda_mode = 0;
    int chars_change = 0;
    int update_delay = 4;
    char *message = NULL;
    char *tty = NULL;
    int color = COLOR_GREEN;

    opterr = 0;
    while ((opt = getopt(argc, argv, "abBcfhlLonsxVu:C:rmkM:t:")) != -1) {
        switch (opt) {
            case 'a': async_scroll = 1; break;
            case 'b': random_bold = 1; break;
            case 'B': all_bold = 1; random_bold = 0; break;
            case 'c': break; // japanese
            case 'f': force_term = 1; break;
            case 'h': print_help(); exit(0);
            case 'l': linux_mode = 1; break;
            case 'L': lock_mode = 1; break;
            case 'o': old_scroll = 1; break;
            case 'n': all_bold = 0; random_bold = 0; break;
            case 's': screensaver = 1; break;
            case 'x': x_mode = 1; break;
            case 'V':
                printf(" CMatrix version 2.0 (compiled 19:59:42, Apr 17 2026)\\n");
                printf("Email: abishekvashok@gmail.com\\n");
                printf("Web: https://github.com/abishekvashok/cmatrix\\n");
                exit(0);
            case 'u': update_delay = atoi(optarg); break;
            case 'C':
                if (strcmp(optarg, "green") == 0) color = COLOR_GREEN;
                else if (strcmp(optarg, "red") == 0) color = COLOR_RED;
                else if (strcmp(optarg, "blue") == 0) color = COLOR_BLUE;
                else if (strcmp(optarg, "white") == 0) color = COLOR_WHITE;
                else if (strcmp(optarg, "yellow") == 0) color = COLOR_YELLOW;
                else if (strcmp(optarg, "cyan") == 0) color = COLOR_CYAN;
                else if (strcmp(optarg, "magenta") == 0) color = COLOR_MAGENTA;
                else if (strcmp(optarg, "black") == 0) color = COLOR_BLACK;
                break;
            case 'r': rainbow_mode = 1; break;
            case 'm': lambda_mode = 1; break;
            case 'k': chars_change = 1; break;
            case 'M': message = optarg; break;
            case 't': tty = optarg; break;
            case '?': print_help(); exit(0);
        }
    }

    srand(time(NULL));

    initscr();
    start_color();
    use_default_colors();
    noecho();
    cbreak();
    nodelay(stdscr, TRUE);
    curs_set(0);

    init_pair(1, COLOR_BLACK, -1);
    init_pair(2, COLOR_RED, -1);
    init_pair(3, COLOR_GREEN, -1);
    init_pair(4, COLOR_YELLOW, -1);
    init_pair(5, COLOR_BLUE, -1);
    init_pair(6, COLOR_MAGENTA, -1);
    init_pair(7, COLOR_CYAN, -1);
    init_pair(8, COLOR_WHITE, -1);

    int max_x, max_y;
    getmaxyx(stdscr, max_y, max_x);

    Column *cols = malloc(max_x * sizeof(Column));
    char **grid = malloc(max_x * sizeof(char *));
    for (int i = 0; i < max_x; i++) {
        cols[i].y = rand() % max_y - max_y;
        cols[i].len = rand() % (max_y - 3) + 3;
        cols[i].speed = async_scroll ? (rand() % 4 + 1) : 1;
        cols[i].tick = 0;
        grid[i] = malloc(max_y * sizeof(char));
        for (int j = 0; j < max_y; j++) {
            grid[i][j] = (rand() % 94) + 33;
        }
    }

    int current_color = color;
    if (current_color == COLOR_BLACK) current_color = 0;

    int running = 1;
    while (running) {
        int ch = getch();
        if (ch != ERR) {
            if (screensaver) {
                running = 0;
                break;
            }
            switch (ch) {
                case 'a': async_scroll = !async_scroll; break;
                case 'b': random_bold = !random_bold; break;
                case 'B': all_bold = 1; random_bold = 0; break;
                case 'n': all_bold = 0; random_bold = 0; break;
                case '!': current_color = COLOR_RED; break;
                case '@': current_color = COLOR_GREEN; break;
                case '#': current_color = COLOR_YELLOW; break;
                case '$': current_color = COLOR_BLUE; break;
                case '%': current_color = COLOR_MAGENTA; break;
                case '^': current_color = COLOR_CYAN; break;
                case '&': current_color = COLOR_WHITE; break;
                case ')': current_color = COLOR_BLACK; break;
                case 'q': running = 0; break;
                default:
                    if (ch >= '0' && ch <= '9') {
                        update_delay = ch - '0';
                    }
                    break;
            }
            if (current_color == COLOR_BLACK) current_color = 0;
        }

        for (int i = 0; i < max_x; i += 2) { // mostly drawn on every other column
            cols[i].tick++;
            if (cols[i].tick >= cols[i].speed) {
                cols[i].tick = 0;

                // Clear the tail
                int tail_y = cols[i].y - cols[i].len;
                if (tail_y >= 0 && tail_y < max_y) {
                    mvaddch(tail_y, i, ' ');
                }

                // Move head
                cols[i].y++;

                // Draw old head with normal color
                if (cols[i].y - 1 >= 0 && cols[i].y - 1 < max_y) {
                    int c_pair = current_color + 1;
                    if (rainbow_mode) c_pair = (rand() % 7) + 2;
                    attron(COLOR_PAIR(c_pair));
                    if (all_bold || (random_bold && rand()%2)) attron(A_BOLD);

                    if (chars_change) grid[i][cols[i].y - 1] = (rand() % 94) + 33;
                    char d_char = grid[i][cols[i].y - 1];
                    if (lambda_mode) d_char = 'm'; // approximation for lambda

                    mvaddch(cols[i].y - 1, i, d_char);

                    attroff(A_BOLD);
                    attroff(COLOR_PAIR(c_pair));
                }

                // Draw new head with white color
                if (cols[i].y >= 0 && cols[i].y < max_y) {
                    attron(COLOR_PAIR(8) | A_BOLD); // White head
                    if (chars_change) grid[i][cols[i].y] = (rand() % 94) + 33;
                    char d_char = grid[i][cols[i].y];
                    if (lambda_mode) d_char = 'm';
                    mvaddch(cols[i].y, i, d_char);
                    attroff(COLOR_PAIR(8) | A_BOLD);
                }

                // Reset column if fully off-screen
                if (tail_y >= max_y) {
                    cols[i].y = 0; // or negative to delay start
                    cols[i].len = rand() % (max_y - 3) + 3;
                    cols[i].speed = async_scroll ? (rand() % 4 + 1) : 1;
                }
            }
        }

        if (message) {
            int msg_len = strlen(message);
            int msg_x = (max_x - msg_len) / 2;
            int msg_y = max_y / 2;
            attron(COLOR_PAIR(8) | A_BOLD);
            mvprintw(msg_y, msg_x, "%s", message);
            attroff(COLOR_PAIR(8) | A_BOLD);
        }

        refresh();
        usleep((update_delay * 10000) + 10000);
    }

    endwin();

    for (int i = 0; i < max_x; i++) free(grid[i]);
    free(grid);
    free(cols);

    return 0;
}
"""
with open("cmatrix.c", "w") as f:
    f.write(c_code)

os.system("gcc cmatrix.c -o cmatrix -lncurses")
EOF
python3 gen_cmatrix.py
"}

