            printf("\x1b[%d;%dH\x1b[37;1m%s\x1b[m", m_y + 1, m_x + 1, msg);
        }

        fflush(stdout);
        usleep(update_delay * 10000 + 10000);
    }

    for (int i = 0; i < x_max; i++) free(grid[i]);
    free(grid);
    free(cols);
    return 0;
}
