                    cols[i].len = rand() % (y_max - 3) + 3;
                    cols[i].speed = async_scroll ? (rand() % 4 + 1) : 1;
                }

                if (chars_change) {
                    for (int k = tail_y + 1; k < cols[i].y; k++) {
                        if (k >= 0 && k < y_max) {
                            if (rand() % 10 == 0) {
                                grid[i][k] = get_rand_char(japanese_mode, lambda_mode);
                                int is_bold = all_bold || (random_bold && (rand() % 2));
                                int c_color = rainbow_mode ? (rand() % 5 + 32) : color;
                                draw_cell(i, k, c_color, is_bold, grid[i][k]);
                            }
                        }
                    }
                }
            }
        }

        if (message || lock_mode) {
            const char *msg = message ? message : "Computer locked.";
            int m_len = strlen(msg);
            int m_y = y_max / 2;
            int m_x = (x_max - m_len) / 2;
            if (m_x < 0) m_x = 0;
            printf("\x1b[%d;%dH\x1b[37;1m%s\x1b[m", m_y + 1, m_x + 1, msg);
        }

        fflush(stdout);
        usleep(update_delay * 10000 + 10000);
    }

    for (int i = 0; i < old_x_max; i++) free(grid[i]);
    free(grid);
    free(cols);
    return 0;
}
